using System;
using System.IO;
using System.Collections.Generic;
using System.Windows;

namespace WhiteDragon {
public static class BehaviorChecks {
    static void Check(bool good,string message){if(!good)throw new Exception(message);}
    public static Dictionary<string,object> Run(string folder) {
        var cases=new List<string>();PetBehavior b;
        b=new PetBehavior(500);b.BeginPress(false,1,0);b.EndPress(40);b.Tick(539,null,false,false);
        Check(b.Animation==0,"single click prematurely jumped");b.Tick(540,null,false,false);Check(b.Animation==4,"single click did not jump");b.Tick(1500,null,false,false);Check(b.Animation==0,"jump did not settle");cases.Add("single_click_waits_for_double_click_window_and_returns_idle");
        b=new PetBehavior(500);b.BeginPress(false,1,0);b.EndPress(30);b.BeginPress(false,2,320);b.EndPress(330);b.Tick(600,null,false,false);
        Check(b.Animation==3&&b.PendingClick==0,"double click leaked a jump");b.Tick(3869,null,false,false);Check(b.Animation==3,"new wave ended before its video");b.Tick(3870,null,false,false);Check(b.Animation==0,"wave did not settle");cases.Add("double_click_has_no_intermediate_jump_and_3550ms_wave_finishes");
        b=new PetBehavior(500);b.BeginPress(true,1,0);b.Drag(1,40);b.Tick(600,null,false,false);Check(b.Animation==14&&!b.Petting,"drag did not suspend");b.Drag(2,620);Check(b.Animation==14,"grab changes to running on reversal");b.EndPress(650);b.Tick(1700,null,false,false);Check(b.Animation==0&&b.PendingClick==0,"drag leaked a click");cases.Add("drag_cancels_click_and_long_press_and_stays_suspended_in_both_directions");
        b=new PetBehavior(500);b.BeginPress(true,1,0);b.Tick(549,null,false,false);Check(!b.Petting,"head pat too early");b.Tick(550,null,false,false);Check(b.Petting&&b.Animation==11,"head hold did not pat");b.Tick(800,null,false,false);b.EndPress(900);b.Tick(4182,null,false,false);Check(b.Animation==11,"new pat ended before its video");b.Tick(4183,null,false,false);Check(b.Animation==0&&b.PendingClick==0,"petting release leaked click");cases.Add("long_head_hold_reacts_and_3633ms_response_finishes_without_jump");
        b=new PetBehavior(500);b.Select(12,1000);b.Tick(9500,90,true,false);Check(b.Sleeping&&b.Row==12,"sleep interrupted by distant gaze");b.BeginPress(false,1,9600);b.EndPress(9620);Check(b.Animation==13&&b.PendingClick==0,"wake did not stretch");b.Tick(11200,null,false,false);Check(b.Animation==0,"wake did not settle");cases.Add("sleep_loops_and_wakes_to_stretch_without_jump");
        b=new PetBehavior(500);b.Tick(180001,null,false,true);Check(b.Sleeping,"automatic nap");b=new PetBehavior(500);b.AutoNap=false;b.Tick(180001,null,false,true);Check(!b.Sleeping,"disabled nap still ran");cases.Add("three_minute_nap_respects_user_toggle");
        b=new PetBehavior(500);b.Play(4,true,0);b.Tick(160,null,false,false);int frame=b.Frame;b.SetPaused(true,170);b.Tick(10000,null,false,false);Check(b.Frame==frame,"paused frames advanced");b.SetPaused(false,10020);b.Tick(10129,null,false,false);Check(b.Frame==frame,"resume lost remaining hold");b.Tick(10130,null,false,false);Check(b.Frame==frame+1,"resume failed");cases.Add("pause_preserves_remaining_frame_duration");
        b=new PetBehavior(500);b.BeginPress(false,1,0);b.EndPress(20);b.SetMenu(true,100);b.SetMenu(false,10000);b.Tick(10500,null,false,false);Check(b.Animation==0&&b.PendingClick==0,"menu leaked click");cases.Add("context_menu_cancels_pending_click");
        b=new PetBehavior(500);b.Play(4,true,0);b.SetMenu(true,100);b.Select(13,30000);b.SetMenu(false,30010);b.Tick(30189,null,false,false);Check(b.Frame==0,"menu selection advanced early");b.Tick(30190,null,false,false);Check(b.Frame==1,"long_open_menu_delayed_new_action");cases.Add("new_action_not_delayed_by_time_spent_in_menu");
        b=new PetBehavior(500);b.Select(12,0);b.ResumeAfterHidden(10000);Check(b.Animation==13,"restored nap did not wake");cases.Add("restore_from_tray_wakes_sleeping_pet");
        Check(PetBehavior.StableDirection(12,0)==0&&PetBehavior.StableDirection(17,0)==1,"gaze hysteresis");Check(PetBehavior.Direction(0,-100)==0&&PetBehavior.Direction(100,0)==4&&PetBehavior.Direction(0,100)==8&&PetBehavior.Direction(-100,0)==12,"cardinal mapping");cases.Add("gaze_boundary_hysteresis_and_four_cardinals");
        var size=new Size(384,416);var second=new Rect(-1920,0,1920,1040);Point p=PetBehavior.Clamp(new Point(-50,980),size,second);Check(p.X==-384&&p.Y==624,"negative monitor bounds");p=PetBehavior.Clamp(new Point(-3000,-500),size,second);Check(p.X==-1920&&p.Y==0,"negative screen recovery");var portrait=new Rect(1920,-1000,1080,1920);p=PetBehavior.Clamp(new Point(4000,2000),size,portrait);Check(p.X+size.Width<=portrait.Right&&p.Y+size.Height<=portrait.Bottom,"portrait bounds");cases.Add("simulated_negative_and_portrait_monitors_keep_feet_visible");
        string data=Path.Combine(folder,"preferences-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(data);string file=Path.Combine(data,"settings.json");
        var pref=new PetPreferences{Left=-1500,Top=120,Size=240,Follow=false,Topmost=false,AutoNap=false};PreferenceStore.Save(file,pref);pref.Size=384;pref.Follow=true;PreferenceStore.Save(file,pref);var restored=PreferenceStore.Load(file);Check(restored.Size==384&&restored.Follow&&File.Exists(file+".bak"),"settings roundtrip");File.WriteAllText(file,"{");restored=PreferenceStore.Load(file);Check(restored.Size==240&&!restored.Follow&&!restored.AutoNap,"backup recovery");cases.Add("atomic_settings_backup_and_malformed_file_recovery_in_test_folder");
        File.WriteAllText(file,"{\"Size\":288,\"Left\":-1200,\"Top\":100,\"Follow\":true,\"Topmost\":false}");restored=PreferenceStore.Load(file);Check(restored.AutoNap&&restored.Left==-1200&&!restored.Topmost,"v3 settings compatibility");cases.Add("v3_settings_remain_readable");
        b=new PetBehavior(500);b.BeginPress(true,1,0);b.Tick(550,null,false,false);Check(b.Petting,"pat start");b.Drag(14,650);Check(b.Dragged&&!b.Petting&&b.Animation==14,"cannot pick up after head pat");b.EndPress(700);Check(b.PendingClick==0&&b.Animation==0,"pat to grab release");cases.Add("head_pat_can_turn_into_pickup_when_pointer_moves");
        b=new PetBehavior(500);b.Select(12,0);b.BeginPress(true,1,100);b.Drag(14,160);Check(b.Dragged&&b.Animation==14,"sleeping pet requires second pickup attempt");b.EndPress(200);Check(b.PendingClick==0,"sleep pickup leaked jump");cases.Add("sleeping_pet_can_be_picked_up_in_one_gesture");
        b=new PetBehavior(500);b.BeginPress(false,1,0);b.Drag(14,50);b.CancelPointer(90);Check(!b.Pressed&&!b.Dragged&&b.Animation==0,"cancel leaves suspended mode");cases.Add("capture_cancel_returns_to_stand_without_pending_click");
        var g=new GrabMotion();g.Begin(0,0,0);for(int i=1;i<=40;i++)g.Step(i*16,i*12,0);Check(g.Angle>10&&g.Angle<=27,"right lag amplitude");double peak=g.Angle;
        for(int i=1;i<=80;i++)g.Step(640+i*16,480,0);Check(Math.Abs(g.Angle)<1,"stationary pointer did not settle");cases.Add("horizontal_swing_has_inertia_and_damps_when_pointer_stops");
        g.Begin(0,0,0);for(int i=1;i<=40;i++)g.Step(i*16,-i*12,0);Check(g.Angle< -10,"left lag sign");cases.Add("horizontal_reversal_changes_swing_direction");
        g.Begin(0,0,0);for(int i=1;i<=40;i++)g.Step(i*16,0,-i*12);Check(g.Stretch>1.01,"up motion did not stretch");g.Begin(0,0,0);for(int i=1;i<=40;i++)g.Step(i*16,0,i*12);Check(g.Stretch<.99,"down motion did not compress");cases.Add("vertical_motion_reacts_in_both_directions");
        g.End(1000);g.Step(1120,0,0);Check(g.Stretch<1&&!g.Active,"landing bounce missing");g.Step(1240,0,0);Check(!g.Landing&&g.Stretch==1&&g.Angle==0,"landing did not settle");cases.Add("release_has_short_landing_and_no_persistent_rotation");
        foreach(int hz in new int[]{30,60,120}){g.Begin(0,0,0);for(int i=1;i<=hz;i++)g.Step((long)Math.Round(i*1000.0/hz),i*900.0/hz,0);Check(g.Angle>15&&g.Angle<=27,"frame rate dependent swing");}cases.Add("motion_stays_bounded_at_30_60_120_hz");
        g.Begin(0,0,0);g.Step(16,100000,-100000);Check(Math.Abs(g.Angle)<=27&&g.Stretch>.95&&g.Stretch<1.05,"teleport impulse unbounded");g.Step(5000,1000000,1000000);g.Step(5016,1000000,1000000);Check(!double.IsNaN(g.Angle)&&Math.Abs(g.Angle)<=27,"long stall invalid state");cases.Add("teleports_and_long_stalls_do_not_explode");
        var pivot=new Point(240,174);foreach(double angle in new double[]{-27,27})foreach(double sy in new double[]{.956,1.044})foreach(Point corner in new Point[]{new Point(0,0),new Point(384,0),new Point(384,416),new Point(0,416)}){Point t=GrabMotion.Transform(corner,angle,sy,pivot);Check(t.X>=-128&&t.X<=512&&t.Y>=-128&&t.Y<=544,"swing clipped by native window");}cases.Add("padded_window_contains_rotated_and_stretched_full_cell");
        var trace=new List<double[]>();g.Begin(0,0,0);for(int i=1;i<=120;i++){double x=220*Math.Sin(i*.04),y=100*Math.Cos(i*.07)-100;g.Step(i*16,x,y);if(i%10==0)trace.Add(new double[]{i*16,x,y,g.Angle,g.Stretch});}
        var flight=ThrowFlightChecks.Run();cases.AddRange((string[])flight["cases"]);
        return new Dictionary<string,object>{{"behavior_cases",cases},{"behavior_case_count",cases.Count},{"main_actions",14},{"look_directions",16},{"additional_frames_v4",18},{"additional_grab_frames",4},{"additional_flight_cells",4},{"right_swing_peak_degrees",peak},{"motion_parity_trace",trace},{"flight_parity_trace",flight["flight_parity_trace"]},{"throw_threshold_dip_per_second",flight["throw_threshold_dip_per_second"]},{"settings_tests_isolated_from_real_user_settings",true}};
    }
}
